import{_ as a,o as t,c as i,ae as o}from"./chunks/framework.1Lna8NcP.js";const u=JSON.parse('{"title":"User Guide (Happy Path)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/user-guide.md","filePath":"guide/user-guide.md"}'),r={name:"guide/user-guide.md"};function s(n,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="user-guide-happy-path" tabindex="-1">User Guide (Happy Path) <a class="header-anchor" href="#user-guide-happy-path" aria-label="Permalink to &quot;User Guide (Happy Path)&quot;">​</a></h1><p>This is the fastest path to getting useful results from Libertas.</p><h2 id="_1-start-libertas" tabindex="-1">1. Start Libertas <a class="header-anchor" href="#_1-start-libertas" aria-label="Permalink to &quot;1. Start Libertas&quot;">​</a></h2><p>From the repo root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span></span></code></pre></div><p>Open the frontend dev URL printed by the script (<code>http://localhost:5173</code> or <code>http://localhost:5174</code>).</p><h2 id="_2-pick-your-theme" tabindex="-1">2. Pick your theme <a class="header-anchor" href="#_2-pick-your-theme" aria-label="Permalink to &quot;2. Pick your theme&quot;">​</a></h2><p>Go to <code>Settings</code> → <code>Appearance</code>:</p><ul><li><code>Onyx</code> for dark mode</li><li><code>Retro</code> for blue mode</li></ul><h2 id="_3-bring-in-your-first-data" tabindex="-1">3. Bring in your first data <a class="header-anchor" href="#_3-bring-in-your-first-data" aria-label="Permalink to &quot;3. Bring in your first data&quot;">​</a></h2><p>Choose one of these:</p><ul><li>Upload in <code>Import</code> page (<code>CSV</code> or <code>Excel</code>)</li><li>Drop files into <code>data/watch/</code> and let auto-ingest run</li><li>Add/edit accounts manually in <code>Accounts</code></li></ul><p>After import, Libertas rebuilds holdings and snapshots automatically.</p><h2 id="_4-review-the-overview-page" tabindex="-1">4. Review the Overview page <a class="header-anchor" href="#_4-review-the-overview-page" aria-label="Permalink to &quot;4. Review the Overview page&quot;">​</a></h2><p>Use <code>/</code> (Overview) to verify:</p><ul><li>Net worth trend and recent delta</li><li>Allocation chart</li><li>Account cards and freshness indicators</li><li>News panel</li></ul><p>If values look stale, run <code>Settings</code> → <code>Refresh prices</code>.</p><h2 id="_5-use-core-planning-pages" tabindex="-1">5. Use core planning pages <a class="header-anchor" href="#_5-use-core-planning-pages" aria-label="Permalink to &quot;5. Use core planning pages&quot;">​</a></h2><ul><li><code>Debt</code>: view payoff strategy options + what-if extra payments</li><li><code>Retirement</code>: evaluate projection and plan assumptions</li><li><code>Taxes</code>: estimate liability and review harvesting/entity guidance</li><li><code>Insights</code>: read deterministic insights and optional AI responses</li></ul><h2 id="_6-protect-your-data" tabindex="-1">6. Protect your data <a class="header-anchor" href="#_6-protect-your-data" aria-label="Permalink to &quot;6. Protect your data&quot;">​</a></h2><p>In <code>Settings</code>:</p><ul><li>Create periodic backups</li><li>Select encryption mode (<code>macOS Keychain</code> default, or passphrase)</li><li>Keep your passphrase safe if passphrase mode is enabled</li></ul><h2 id="_7-roll-back-bad-imports-if-needed" tabindex="-1">7. Roll back bad imports if needed <a class="header-anchor" href="#_7-roll-back-bad-imports-if-needed" aria-label="Permalink to &quot;7. Roll back bad imports if needed&quot;">​</a></h2><p>If an import looked wrong:</p><ul><li>Open <code>Import</code></li><li>Use rollback on the specific import log entry</li></ul><p>Rollback removes transactions tied to that import and rebuilds holdings/snapshots.</p><h2 id="_8-optional-ai-and-integrations" tabindex="-1">8. Optional AI and integrations <a class="header-anchor" href="#_8-optional-ai-and-integrations" aria-label="Permalink to &quot;8. Optional AI and integrations&quot;">​</a></h2><p>You can use Libertas fully without any API keys.</p><p>For optional capabilities, continue to <a href="/Libertas/guide/api-keys-and-integrations.html">API Keys &amp; Integrations</a>.</p>',29)])])}const g=a(r,[["render",s]]);export{u as __pageData,g as default};
